/** Registers global API 403 navigator. Renders children after registration. */
const ApiErrorHandler: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const navigate = useNavigate();
  useEffect(() => {
    registerApiNavigationHandler((event) => {
      if (event.method !== 'GET') return; // chỉ GET (load page)
      // 404: không navigate not-found — để toast / inline error
      if (event.statusCode !== 403) return;
      try {
        sessionStorage.setItem(
          ERR_SESSION_KEY,
          window.location.pathname + window.location.search,
        );
      } catch { /* noop */ }
      // Shell: navigateToUrl so URL bar + MemoryRouterSync stay aligned
      navigateInAppPath('/forbidden', navigate, { replace: true });
    });
    return () => unregisterApiNavigationHandler();
  }, [navigate]);
  return <>{children}</>;
};

